// @vitest-environment jsdom
import{beforeEach,afterEach,describe,it,expect,vi}from'vitest';
function deferred<T>(){let resolve!:(value:T)=>void;const promise=new Promise<T>(r=>resolve=r);return{resolve,promise};}
function json(body:unknown){return{ok:true,status:200,json:async()=>body}as Response;}
beforeEach(()=>{vi.resetModules();localStorage.clear();});afterEach(()=>{vi.clearAllTimers();vi.useRealTimers();vi.unstubAllGlobals();vi.restoreAllMocks();});
describe('cross-tab cookie/session boundaries',()=>{
 it('does not give B the in-flight A GET when another tab changed the cookie before session lookup',async()=>{const client=await import('@/api/client');const a=deferred<Response>();const fetch=vi.fn().mockReturnValueOnce(a.promise).mockResolvedValueOnce(json({actor:'B'}));vi.stubGlobal('fetch',fetch);const previous=client.api.get('/fixture/private');const previousOutcome=previous.catch(error=>error);localStorage.setItem('paperclip.auth-session-epoch',JSON.stringify({epoch:'other-tab-login-B',phase:'settled'}));const current=client.api.get('/fixture/private');a.resolve(json({actor:'A',privateValue:'A-only'}));expect(await current).toEqual({actor:'B'});expect(await previousOutcome).toMatchObject({name:'AbortError'});expect(fetch).toHaveBeenCalledTimes(2);});
 it('rejects an A body that finishes decoding only after the cookie epoch changed',async()=>{const client=await import('@/api/client');const body=deferred<unknown>();vi.stubGlobal('fetch',vi.fn().mockResolvedValue({ok:true,status:200,json:()=>body.promise}));const old=client.api.get('/fixture/late-body').catch(error=>error);await Promise.resolve();localStorage.setItem('paperclip.auth-session-epoch',JSON.stringify({epoch:'new-account-B',phase:'settled'}));window.dispatchEvent(new StorageEvent('storage',{key:'paperclip.auth-session-epoch',newValue:localStorage.getItem('paperclip.auth-session-epoch')}));body.resolve({actor:'A'});expect(await old).toMatchObject({name:'AbortError'});});
 it('does not duplicate a write when account change leaves a mutation outcome uncertain',async()=>{const client=await import('@/api/client');const write=deferred<Response>();const fetch=vi.fn().mockReturnValue(write.promise);vi.stubGlobal('fetch',fetch);const request=client.api.post('/fixture/write',{value:1});localStorage.setItem('paperclip.auth-session-epoch',JSON.stringify({epoch:'other-account',phase:'settled'}));write.resolve(json({created:true}));await request;expect(fetch).toHaveBeenCalledTimes(1);});
 it('keeps same-account GET coalescing and per-caller cancellation intact',async()=>{const client=await import('@/api/client');const response=deferred<Response>();const fetch=vi.fn().mockReturnValue(response.promise);vi.stubGlobal('fetch',fetch);const controller=new AbortController();const cancelled=client.api.get('/fixture/same',{signal:controller.signal}).catch(error=>error);const active=client.api.get('/fixture/same');controller.abort();response.resolve(json({actor:'same'}));expect(await cancelled).toMatchObject({name:'AbortError'});expect(await active).toEqual({actor:'same'});expect(fetch).toHaveBeenCalledTimes(1);});
 it('observes an already pending marker on a newly opened tab without trusting an identity',async()=>{localStorage.setItem('paperclip.auth-session-epoch',JSON.stringify({epoch:'sender-in-progress',phase:'pending',expiresAt:Date.now()+30_000}));const client=await import('@/api/client');const fetch=vi.fn();vi.stubGlobal('fetch',fetch);expect(client.isApiSessionChangePending()).toBe(true);await expect(client.api.get('/fixture/private')).rejects.toMatchObject({name:'AbortError'});expect(fetch).not.toHaveBeenCalled();});
 it('recovers a crashed sender after bounded expiry and verifies the actual session with no cached account',async()=>{vi.useFakeTimers();const client=await import('@/api/client');const auth=await import('@/api/auth');const boundary=vi.fn();const unsubscribe=client.subscribeAccountCacheBoundary(boundary);localStorage.setItem('paperclip.auth-session-epoch',JSON.stringify({epoch:'closed-sender',phase:'pending',expiresAt:Date.now()+30_000}));expect(client.isApiSessionChangePending()).toBe(true);await expect(auth.authApi.getSession()).rejects.toMatchObject({name:'AbortError'});vi.stubGlobal('fetch',vi.fn().mockResolvedValue(json(null)));await vi.advanceTimersByTimeAsync(30_000);expect(client.isApiSessionChangePending()).toBe(false);expect(await auth.authApi.getSession()).toBeNull();expect(fetch).toHaveBeenCalledTimes(1);/* 1.1.6：pending 只阻断读写，不重挂载；同一 epoch 的边界只在 settled 或过期时触发一次。 */expect(boundary).toHaveBeenCalledTimes(1);unsubscribe();});
 it('never dispatches React account boundary synchronously from a getter',async()=>{const client=await import('@/api/client');const boundary=vi.fn();const unsubscribe=client.subscribeAccountCacheBoundary(boundary);localStorage.setItem('paperclip.auth-session-epoch',JSON.stringify({epoch:'peer-B',phase:'settled'}));client.getApiSessionEpoch();expect(boundary).not.toHaveBeenCalled();await Promise.resolve();expect(boundary).toHaveBeenCalledOnce();unsubscribe();});
 it('keeps same-tab fencing operational when browser storage is unavailable',async()=>{vi.spyOn(Storage.prototype,'getItem').mockImplementation(()=>{throw new DOMException('blocked','SecurityError')});vi.spyOn(Storage.prototype,'setItem').mockImplementation(()=>{throw new DOMException('blocked','SecurityError')});const client=await import('@/api/client');const fetch=vi.fn().mockResolvedValue(json({same:true}));vi.stubGlobal('fetch',fetch);const startEpoch=client.getApiSessionEpoch();const finish=client.beginApiSessionChange(true);expect(client.isApiSessionChangePending()).toBe(true);finish();expect(client.isApiSessionChangePending()).toBe(false);expect(client.getApiSessionEpoch()).toBeGreaterThan(startEpoch);expect(await client.api.get('/fixture/same')).toEqual({same:true});});

 it('lets normal sender login finish without remounting its auth form, then verifies the real session',async()=>{const client=await import('@/api/client');const auth=await import('@/api/auth');const response=deferred<Response>();const fetch=vi.fn().mockReturnValueOnce(response.promise).mockResolvedValueOnce(json(null));vi.stubGlobal('fetch',fetch);const boundary=vi.fn();const unsubscribe=client.subscribeAccountCacheBoundary(boundary);const login=auth.authApi.signInEmail({email:'fixture@example.invalid',password:'fixture-only'});expect(JSON.parse(localStorage.getItem('paperclip.auth-session-epoch')!).phase).toBe('pending');expect(client.isApiSessionChangePending()).toBe(true);response.resolve(json({success:true}));await login;await Promise.resolve();expect(JSON.parse(localStorage.getItem('paperclip.auth-session-epoch')!).phase).toBe('settled');expect(boundary).not.toHaveBeenCalled();expect(client.isApiSessionChangePending()).toBe(false);expect(await auth.authApi.getSession()).toBeNull();expect(fetch).toHaveBeenCalledTimes(2);unsubscribe();});

 it.each(['pending','settled'])('blocks stale A first POST after peer %s cookie change before session lookup or storage event',async phase=>{const client=await import('@/api/client');const fetch=vi.fn().mockResolvedValue(json({written:true}));vi.stubGlobal('fetch',fetch);localStorage.setItem('paperclip.auth-session-epoch',JSON.stringify({epoch:'peer-new-B',phase,expiresAt:Date.now()+30_000}));await expect(client.api.post('/fixture/secret',{privateValue:'A'})).rejects.toBeInstanceOf(client.ApiSessionChangedError);expect(fetch).not.toHaveBeenCalled();});
 it('holds writes until the new account QueryClient has actually remounted, not merely notified',async()=>{const client=await import('@/api/client');const fetch=vi.fn().mockResolvedValue(json({written:true}));vi.stubGlobal('fetch',fetch);localStorage.setItem('paperclip.auth-session-epoch',JSON.stringify({epoch:'peer-new-B',phase:'settled'}));client.getApiSessionEpoch();await Promise.resolve();await expect(client.api.post('/fixture/write',{owner:'A'})).rejects.toBeInstanceOf(client.ApiSessionChangedError);expect(fetch).not.toHaveBeenCalled();client.completeAccountCacheBoundary(client.getApiSessionEpoch());expect(await client.api.post('/fixture/write',{owner:'B'})).toEqual({written:true});expect(fetch).toHaveBeenCalledOnce();});

 it('cannot reopen write dispatch with an acknowledgement for an older boundary',async()=>{const client=await import('@/api/client');const fetch=vi.fn().mockResolvedValue(json({written:true}));vi.stubGlobal('fetch',fetch);localStorage.setItem('paperclip.auth-session-epoch',JSON.stringify({epoch:'B',phase:'settled'}));const bEpoch=client.getApiSessionEpoch();localStorage.setItem('paperclip.auth-session-epoch',JSON.stringify({epoch:'C',phase:'settled'}));const cEpoch=client.getApiSessionEpoch();client.completeAccountCacheBoundary(bEpoch);await expect(client.api.post('/fixture/write',{owner:'old'})).rejects.toBeInstanceOf(client.ApiSessionChangedError);expect(fetch).not.toHaveBeenCalled();client.completeAccountCacheBoundary(cEpoch);await client.api.post('/fixture/write',{owner:'C'});expect(fetch).toHaveBeenCalledOnce();});

 // 1.1.6 回归：标记键永不删除，冷加载读到历史 settled 标记不是身份变化，不能整树 remount。
 it('does not treat a historical settled marker as an account change on cold load',async()=>{localStorage.setItem('paperclip.auth-session-epoch',JSON.stringify({epoch:'login-from-yesterday',phase:'settled',expiresAt:Date.now()-86_400_000}));const client=await import('@/api/client');const fetch=vi.fn().mockResolvedValue(json({written:true}));vi.stubGlobal('fetch',fetch);const boundary=vi.fn();const unsubscribe=client.subscribeAccountCacheBoundary(boundary);const start=client.getApiSessionEpoch();await Promise.resolve();await Promise.resolve();expect(boundary).not.toHaveBeenCalled();expect(client.isApiSessionChangePending()).toBe(false);expect(client.getApiSessionEpoch()).toBe(start);expect(await client.api.post('/fixture/write',{owner:'same'})).toEqual({written:true});expect(fetch).toHaveBeenCalledOnce();unsubscribe();});
 // 1.1.6 回归：另一标签同账号重登会依次写 pending/settled（同一 epoch），本标签最多一次边界。
 it('fires at most one boundary for a peer pending then settled login of the same epoch',async()=>{const client=await import('@/api/client');const boundary=vi.fn();const unsubscribe=client.subscribeAccountCacheBoundary(boundary);const key='paperclip.auth-session-epoch';const emit=(phase:string)=>{localStorage.setItem(key,JSON.stringify({epoch:'peer-relogin-1',phase,expiresAt:Date.now()+30_000}));/* 用 getter 同步而非全局 StorageEvent：先前用例的旧模块实例也监听 window，会干扰计数。 */client.getApiSessionEpoch();};emit('pending');await Promise.resolve();expect(client.isApiSessionChangePending()).toBe(true);emit('settled');await Promise.resolve();await Promise.resolve();expect(client.isApiSessionChangePending()).toBe(false);expect(boundary).toHaveBeenCalledTimes(1);client.getApiSessionEpoch();await Promise.resolve();expect(boundary).toHaveBeenCalledTimes(1);unsubscribe();});
 // 1.1.6 回归：边界事件若早于 React 订阅者挂载，订阅时必须消费，否则非 GET 会永久抛 ApiSessionChangedError。
 it('lets a late subscriber consume a boundary that was announced before it mounted',async()=>{const client=await import('@/api/client');const fetch=vi.fn().mockResolvedValue(json({written:true}));vi.stubGlobal('fetch',fetch);localStorage.setItem('paperclip.auth-session-epoch',JSON.stringify({epoch:'peer-before-mount',phase:'settled'}));client.getApiSessionEpoch();await Promise.resolve();await expect(client.api.post('/fixture/write',{owner:'old'})).rejects.toBeInstanceOf(client.ApiSessionChangedError);const boundary=vi.fn(()=>client.completeAccountCacheBoundary(client.getApiSessionEpoch()));const unsubscribe=client.subscribeAccountCacheBoundary(boundary);await Promise.resolve();await Promise.resolve();expect(boundary).toHaveBeenCalledOnce();expect(await client.api.post('/fixture/write',{owner:'new'})).toEqual({written:true});expect(fetch).toHaveBeenCalledOnce();unsubscribe();});

});
